32	 ****************************************************************************/
33	
34	/* SPI1 is the controller behind the DevKit display FPC "QSPI1" net.  Its
35	 * four pads (CLK/CS/MOSI/MISO = GPIO2/3/4/5) are the SPI1 peripheral mux
36	 * option 0.  The base is SOC_SPI_REG_BASE + 0x1010000 * unit.
37	 */
38	
39	#define BK7258_SPI0_BASE       UINT32_C(0x44870000)
40	#define BK7258_SPI1_BASE       UINT32_C(0x45880000)
41	#define BK7258_SPI1_STRIDE     UINT32_C(0x01010000)
42	
43	/* System control registers shared with the CP bring-up.  The device clock
44	 * gate (SYS_BASE+0x30) already exists as BK7258_SYS_DEV_CLK_EN; spi1_cken
45	 * is bit 9.  The SPI clock source select register (SYS_BASE+0x28) holds
46	 * clksel_spi1 at bit 5 (0 = XTAL 26M, 1 = APLL).
47	 */
48	
49	#define BK7258_SYS_BASE       UINT32_C(0x44010000)
50	#define BK7258_SYS_CLKSEL     (BK7258_SYS_BASE + UINT32_C(0x28))
51	#define BK7258_SYS_SPI1_XTAL   UINT32_C(0)          /* clksel_spi1 = 0 */
52	#define BK7258_SYS_SPI1_APLL   (UINT32_C(1) << 5)   /* clksel_spi1 = 1 */
53	#define BK7258_SYS_SPI1_CLK_EN (UINT32_C(1) << 9)   /* spi1_cken in DEV_CLK_EN */
54	
55	/* SPI1 source clock and the resulting maximum SPI baud rate.
56	 * baud = f_src / (2 * clk_rate), so with clk_rate = 1 the top rate is
57	 * f_src / 2.
58	 *
59	 * f_src is the 26 MHz XTAL (clksel_spi1 = 0).  The authority's clock select
60	 * also names an APLL source, but enabling it means programming and powering
61	 * the audio PLL, and no shipped configuration does that for SPI -- so this
62	 * link stays at 13 MHz, which costs ~87 ms per 240x296@16bpp frame and
63	 * 28..45% of the AP core.  The QSPI transport (bk7258_qspi.c) is the way out:
64	 * the same 4-line protocol at 48 MHz through a memory-mapped window.
65	 */
66	
67	#define BK7258_SPI1_SRC_CLK    UINT32_C(26000000)
68	#define BK7258_SPI1_MAX_BAUD   (BK7258_SPI1_SRC_CLK / 2)
69	
70	/* The tx_trans_len field is 12 bits, so a single master transfer is capped
71	 * at 4095 bytes.  Larger bursts are split by the driver while software CS
72	 * stays asserted.
73	 */
74	
75	#define BK7258_SPI_MAX_TRANSFER 4095
