60	#ifdef CONFIG_BK7258_LCD1_SPI_HW
61	
62	/****************************************************************************
63	 * Pre-processor Definitions
64	 ****************************************************************************/
65	
66	/* SPI1 peripheral mux option 0 selects the SPI1 function on GPIO2/3/4/5
67	 * (ARMINO gpio_map.h).  GPIO2=SCK, GPIO4=MOSI are routed to the SPI
68	 * controller; GPIO3=CS and GPIO5=D/C are kept as plain GPIO outputs.
69	 */
70	
71	#define BK7258_SPI1_FUNC_SCK  0
72	#define BK7258_SPI1_FUNC_MOSI 0
73	
74	/* Poll-loop bounds.  Each wait is bounded so a missing FIFO/busy bit can
75	 * never hang the LCD flush path.
76	 */
77	
78	#define BK7258_SPI_WR_READY_MAX  1000000
79	#define BK7258_SPI_FINISH_MAX    10000000
80	
81	/****************************************************************************
82	 * Private Types
83	 ****************************************************************************/
84	
85	struct bk7258_spi_dev_s
86	{
87	  struct spi_dev_s dev;
88	  FAR bk7258_spi_hw_t *hw;   /* SPI1 register block */
89	  mutex_t lock;              /* Mutual exclusion */
90	  uint32_t frequency;        /* Requested frequency */
91	  uint32_t actual;           /* Achieved frequency */
92	  uint8_t mode;              /* Current SPI mode */
93	  uint8_t nbits;             /* Current bit width (8 only) */
94	};
