97	 * Private Function Prototypes
98	 ****************************************************************************/
99	
100	static int      bk7258_spi_lock(FAR struct spi_dev_s *dev, bool lock);
101	static void     bk7258_spi_select(FAR struct spi_dev_s *dev, uint32_t devid,
102	                                  bool selected);
