116	                                    FAR const void *txbuffer,
117	                                    FAR void *rxbuffer, size_t nwords);
118	
119	static void bk7258_spi_transfer(FAR struct bk7258_spi_dev_s *priv,
120	                                FAR const uint8_t *txbuf, FAR uint8_t *rxbuf,
121	                                size_t nwords);
122	
123	/****************************************************************************
124	 * Private Data
125	 ****************************************************************************/
126	
127	static const struct spi_ops_s g_bk7258_spiops =
128	{
129	  bk7258_spi_lock,          /* lock */
130	  bk7258_spi_select,        /* select */
131	  bk7258_spi_setfrequency,  /* setfrequency */
132	  bk7258_spi_setmode,       /* setmode */
133	  bk7258_spi_setbits,       /* setbits */
134	  bk7258_spi_status,        /* status */
135	#ifdef CONFIG_SPI_CMDDATA
136	  bk7258_spi_cmddata,       /* cmddata */
137	#endif
138	  bk7258_spi_send,          /* send */
139	  bk7258_spi_exchange,      /* exchange */
140	  0                         /* registercallback */
141	};
142	
143	static struct bk7258_spi_dev_s g_spidev;
144	
145	/* Source clock actually in use.  The authority's SPI select offers an APLL
146	 * source, but no shipped configuration enables it and no vendor code enables
147	 * the APLL for SPI, so this link stays on the 26 MHz XTAL: 13 MHz at
148	 * clk_rate = 1.  The QSPI transport (bk7258_qspi.c) is the way past it.
149	 */
150	
151	static uint32_t g_spi1_src_clk = 26000000U;
152	
153	
154	/****************************************************************************
155	 * Private Functions
156	 ****************************************************************************/
157	
158	static int bk7258_spi_lock(FAR struct spi_dev_s *dev, bool lock)
159	{
160	  FAR struct bk7258_spi_dev_s *priv = (FAR struct bk7258_spi_dev_s *)dev;
161	  int ret;
162	
163	  if (lock)
164	    {
165	      ret = nxmutex_lock(&priv->lock);
166	    }
167	  else
168	    {
169	      ret = nxmutex_unlock(&priv->lock);
170	    }
171	
172	  return ret;
173	}
174	
175	static void bk7258_spi_select(FAR struct spi_dev_s *dev, uint32_t devid,
176	                              bool selected)
177	{
178	  /* Active-low chip select driven by GPIO3 */
179	
180	  bk7258_gpio_write(BOARD_LCD_CS_PIN, !selected);
181	}
182	
183	static uint32_t bk7258_spi_setfrequency(FAR struct spi_dev_s *dev,
184	                                        uint32_t frequency)
185	{
186	  FAR struct bk7258_spi_dev_s *priv = (FAR struct bk7258_spi_dev_s *)dev;
187	  uint32_t clk_rate;
188	
189	  if (frequency > BK7258_SPI1_MAX_BAUD)
190	    {
191	      frequency = BK7258_SPI1_MAX_BAUD;
192	    }
193	
194	  /* baud = f_src / (2 * clk_rate), round up to stay below the request */
195	
196	  clk_rate = (g_spi1_src_clk + (2 * frequency) - 1) / (2 * frequency);
197	  if (clk_rate < 1)
198	    {
199	      clk_rate = 1;
200	    }
201	  else if (clk_rate > 0xff)
202	    {
203	      clk_rate = 0xff;
204	    }
205	
206	  priv->hw->ctrl.clk_rate = clk_rate;
207	
208	  priv->frequency = frequency;
209	  priv->actual    = g_spi1_src_clk / (2 * clk_rate);
210	
211	  return priv->actual;
212	}
213	
214	static void bk7258_spi_setmode(FAR struct spi_dev_s *dev,
215	                               enum spi_mode_e mode)
216	{
217	  FAR struct bk7258_spi_dev_s *priv = (FAR struct bk7258_spi_dev_s *)dev;
218	
219	  switch (mode)
220	    {
221	      case SPIDEV_MODE0: /* CPOL=0 CPHA=0 */
222	        priv->hw->ctrl.cpol = 0;
223	        priv->hw->ctrl.cpha = 0;
224	        break;
225	
226	      case SPIDEV_MODE1: /* CPOL=0 CPHA=1 */
227	        priv->hw->ctrl.cpol = 0;
228	        priv->hw->ctrl.cpha = 1;
229	        break;
230	
231	      case SPIDEV_MODE2: /* CPOL=1 CPHA=0 */
232	        priv->hw->ctrl.cpol = 1;
233	        priv->hw->ctrl.cpha = 0;
234	        break;
235	
236	      case SPIDEV_MODE3: /* CPOL=1 CPHA=1 */
237	        priv->hw->ctrl.cpol = 1;
238	        priv->hw->ctrl.cpha = 1;
239	        break;
240	
241	      default:
242	        printf("SPI1: ERROR invalid mode %d\n", mode);
243	        return;
244	    }
245	
246	  priv->mode = mode;
247	}
248	
249	static void bk7258_spi_setbits(FAR struct spi_dev_s *dev, int nbits)
250	{
251	  FAR struct bk7258_spi_dev_s *priv = (FAR struct bk7258_spi_dev_s *)dev;
252	
253	  if (nbits != 8)
254	    {
255	      printf("SPI1: ERROR only 8-bit (%d)\n", nbits);
256	      return;
257	    }
258	
259	  priv->hw->ctrl.bit_width = 0; /* 8-bit */
260	  priv->nbits = nbits;
261	}
262	
263	static uint8_t bk7258_spi_status(FAR struct spi_dev_s *dev, uint32_t devid)
264	{
265	  return 0;
266	}
267	
268	#ifdef CONFIG_SPI_CMDDATA
269	static int bk7258_spi_cmddata(FAR struct spi_dev_s *dev, uint32_t devid,
270	                              bool cmd)
271	{
272	  /* D/C line: low for command, high for data (same polarity as the
273	   * bit-bang lower-half).
274	   */
275	
276	  bk7258_gpio_write(BOARD_LCD_DC_PIN, !cmd);
277	  return OK;
278	}
279	#endif
280	
281	static uint32_t bk7258_spi_send(FAR struct spi_dev_s *dev, uint32_t wd)
282	{
283	  FAR struct bk7258_spi_dev_s *priv = (FAR struct bk7258_spi_dev_s *)dev;
284	  uint8_t tx = (uint8_t)wd;
285	  uint8_t rx;
286	
287	  bk7258_spi_transfer(priv, &tx, &rx, 1);
288	  return rx;
289	}
290	
291	static void bk7258_spi_exchange(FAR struct spi_dev_s *dev,
292	                                FAR const void *txbuffer,
293	                                FAR void *rxbuffer, size_t nwords)
294	{
295	  FAR struct bk7258_spi_dev_s *priv = (FAR struct bk7258_spi_dev_s *)dev;
296	
297	  bk7258_spi_transfer(priv, (FAR const uint8_t *)txbuffer,
298	                      (FAR uint8_t *)rxbuffer, nwords);
299	}
300	
301	static void bk7258_spi_transfer(FAR struct bk7258_spi_dev_s *priv,
302	                                FAR const uint8_t *txbuf, FAR uint8_t *rxbuf,
303	                                size_t nwords)
304	{
305	  FAR bk7258_spi_hw_t *hw = priv->hw;
306	  uint32_t timeout;
307	
308	  while (nwords > 0)
309	    {
310	      size_t chunk = nwords > BK7258_SPI_MAX_TRANSFER ?
311	                     BK7258_SPI_MAX_TRANSFER : nwords;
312	      size_t i;
313	
314	      /* Start a master transmit of exactly `chunk` bytes.  Software CS is
315	       * already held low by jd9853/gc9d01 select() across a burst, so the
316	       * panel sees one continuous CS-low window even when the 4095-byte
317	       * hardware transfer cap forces chunking.
318	       */
319	
320	      hw->int_status.tx_fifo_clr = 1;   /* write-1-clear FIFO */
321	      hw->cfg.tx_trans_len = chunk;
322	      hw->cfg.tx_en = 1;
323	
324	      for (i = 0; i < chunk; i++)
325	        {
326	          timeout = BK7258_SPI_WR_READY_MAX;
327	          while (!hw->int_status.tx_fifo_wr_ready)
328	            {
329	              if (--timeout == 0)
330	                {
331	                  printf("SPI1: ERROR tx fifo not ready (status=%08x)\n",
332	                         (unsigned int)hw->int_status.v);
333	                  goto next_chunk;
334	                }
335	            }
336	
337	          hw->data.fifo_data = txbuf != NULL ? txbuf[i] : 0xff;
338	        }
339	
340	      /* Wait for the last byte to shift out before the next chunk. */
341	
342	      timeout = BK7258_SPI_FINISH_MAX;
343	      while (!hw->int_status.tx_finish_int)
344	        {
345	          if (--timeout == 0)
346	            {
347	              printf("SPI1: ERROR tx finish timeout "
348	                     "(status=%08x cfg=%08x dev_status=%08x)\n",
349	                     (unsigned int)hw->int_status.v,
350	                     (unsigned int)hw->cfg.v,
351	                     (unsigned int)hw->dev_status);
352	              break;
353	            }
354	        }
355	
356	next_chunk:
357	      hw->int_status.tx_finish_int = 1;  /* write-1-clear */
358	      hw->int_status.tx_fifo_int   = 1;  /* write-1-clear */
359	      hw->cfg.tx_en = 0;
360	
361	      if (txbuf != NULL)
362	        {
363	          txbuf += chunk;
364	        }
365	
366	      if (rxbuf != NULL)
367	        {
368	          memset(rxbuf, 0, chunk);
369	          rxbuf += chunk;
370	        }
371	
372	      nwords -= chunk;
373	    }
374	}
375	
376	/****************************************************************************
377	 * Public Functions
378	 ****************************************************************************/
379	
380	FAR struct spi_dev_s *bk7258_spi_initialize(void)
381	{
382	  FAR struct bk7258_spi_dev_s *priv = &g_spidev;
383	  FAR bk7258_spi_hw_t *hw = (FAR bk7258_spi_hw_t *)BK7258_SPI1_BASE;
384	  uint32_t regval;
385	
386	  /* Enable the SPI1 clock gate.  clksel_spi1 stays 0, i.e. the 26 MHz XTAL:
387	   * switching it to the APLL is what the authority's spi_hal does for rates
388	   * above XTAL, but that path also programs and powers the audio PLL, and it
389	   * is not what any shipped configuration uses.
390	   */
391	
392	  regval  = getreg32(BK7258_SYS_DEV_CLK_EN);
393	  regval |= BK7258_SYS_SPI1_CLK_EN;
394	  putreg32(regval, BK7258_SYS_DEV_CLK_EN);
395	
396	  regval  = getreg32(BK7258_SYS_CLKSEL);
397	  regval &= ~BK7258_SYS_SPI1_APLL;
398	  putreg32(regval, BK7258_SYS_CLKSEL);
399	
400	  /* Route SCK (GPIO2) and MOSI (GPIO4) to the SPI1 controller.  CS
401	   * (GPIO3) and D/C (GPIO5) stay plain GPIO outputs.
402	   */
403	
404	  bk7258_gpio_periph(BOARD_LCD_SCL_PIN, BK7258_SPI1_FUNC_SCK);
405	  bk7258_gpio_periph(BOARD_LCD_SDA_PIN, BK7258_SPI1_FUNC_MOSI);
406	  bk7258_gpio_config_output(BOARD_LCD_CS_PIN, false);
407	  bk7258_gpio_config_output(BOARD_LCD_DC_PIN, false);
408	
409	  /* Idle levels: CS de-asserted high, D/C low until a transfer begins. */
410	
411	  bk7258_gpio_write(BOARD_LCD_CS_PIN, true);
412	  bk7258_gpio_write(BOARD_LCD_DC_PIN, false);
413	
414	  /* Bring the controller out of reset.  soft_reset is a low-active reset
415	   * bit: the ARMINO spi_ll_init() sets it to 1 and keeps it there (the
416	   * controller is out of reset while it is 1).  The earlier draft cleared
417	   * it back to 0, which held the shift engine in reset: registers stayed
418	   * writable through AHB but SCK never ran and tx_finish_int never fired.
419	   */
