120	      uint32_t bit_width:            1;  /* bit[18] 0: 8bit, 1: 16bit */
121	      uint32_t lsb_first_en:         1;  /* bit[19] 0: MSB first, 1: LSB first */
122	      uint32_t cpol:                 1;  /* bit[20] */
123	      uint32_t cpha:                 1;  /* bit[21] */
124	      uint32_t master_en:            1;  /* bit[22] */
125	      uint32_t enable:               1;  /* bit[23] */
126	      uint32_t byte_interval:        6;  /* bit[24:29] */
127	      uint32_t reserved:             2;  /* bit[30:31] */
128	    };
129	    uint32_t v;
130	  } ctrl;
