376	/****************************************************************************
377	 * Public Functions
378	 ****************************************************************************/
379	
380	FAR struct spi_dev_s *bk7258_spi_initialize(void)
381	{
382	  FAR struct bk7258_spi_dev_s *priv = &g_spidev;
383	  FAR bk7258_spi_hw_t *hw = (FAR bk7258_spi_hw_t *)BK7258_SPI1_BASE;
384	  uint32_t regval;
385	
386	  /* Enable the SPI1 clock gate.  clksel_spi1 stays 0, i.e. the 26 MHz XTAL:
387	   * switching it to the APLL is what the authority's spi_hal does for rates
388	   * above XTAL, but that path also programs and powers the audio PLL, and it
389	   * is not what any shipped configuration uses.
390	   */
391	
392	  regval  = getreg32(BK7258_SYS_DEV_CLK_EN);
393	  regval |= BK7258_SYS_SPI1_CLK_EN;
394	  putreg32(regval, BK7258_SYS_DEV_CLK_EN);
395	
396	  regval  = getreg32(BK7258_SYS_CLKSEL);
397	  regval &= ~BK7258_SYS_SPI1_APLL;
398	  putreg32(regval, BK7258_SYS_CLKSEL);
399	
400	  /* Route SCK (GPIO2) and MOSI (GPIO4) to the SPI1 controller.  CS
401	   * (GPIO3) and D/C (GPIO5) stay plain GPIO outputs.
402	   */
403	
404	  bk7258_gpio_periph(BOARD_LCD_SCL_PIN, BK7258_SPI1_FUNC_SCK);
405	  bk7258_gpio_periph(BOARD_LCD_SDA_PIN, BK7258_SPI1_FUNC_MOSI);
406	  bk7258_gpio_config_output(BOARD_LCD_CS_PIN, false);
407	  bk7258_gpio_config_output(BOARD_LCD_DC_PIN, false);
408	
409	  /* Idle levels: CS de-asserted high, D/C low until a transfer begins. */
410	
411	  bk7258_gpio_write(BOARD_LCD_CS_PIN, true);
412	  bk7258_gpio_write(BOARD_LCD_DC_PIN, false);
413	
414	  /* Bring the controller out of reset.  soft_reset is a low-active reset
415	   * bit: the ARMINO spi_ll_init() sets it to 1 and keeps it there (the
416	   * controller is out of reset while it is 1).  The earlier draft cleared
417	   * it back to 0, which held the shift engine in reset: registers stayed
418	   * writable through AHB but SCK never ran and tx_finish_int never fired.
419	   */
420	
421	  hw->global_ctrl.soft_reset = 1;
422	
423	  hw->ctrl.v = 0;
424	  hw->cfg.v  = 0;
425	  hw->int_status.v = 0xffff;  /* clear sticky status */
426	
427	  /* Mirror the ARMINO spi_hal_configure() interrupt enables. */
428	
429	  hw->ctrl.tx_udf_int_en = 1;
430	  hw->ctrl.rx_ovf_int_en = 1;
431	  hw->ctrl.tx_fifo_int_en = 0;
432	  hw->ctrl.rx_fifo_int_en = 1;
433	
434	  hw->ctrl.master_en    = 1;  /* master role */
435	  hw->ctrl.bit_width    = 0;  /* 8-bit */
436	  hw->ctrl.lsb_first_en = 0;  /* MSB first */
437	  hw->ctrl.wire3_en     = 0;  /* 4-wire (MOSI/MISO) */
438	  hw->ctrl.cpol         = 0;  /* mode 0 */
439	  hw->ctrl.cpha         = 0;
440	  hw->ctrl.enable       = 1;
441	
442	  hw->cfg.tx_finish_int_en = 1;
443	  hw->cfg.rx_finish_int_en = 1;
444	
445	  hw->int_status.tx_fifo_int = 1;        /* write-1-clear */
446	  hw->int_status.rx_fifo_int = 1;        /* write-1-clear */
447	
448	  priv->hw       = hw;
449	  priv->frequency = 0;
450	  priv->actual    = 0;
451	  priv->mode      = SPIDEV_MODE0;
452	  priv->nbits     = 8;
453	  priv->dev.ops   = &g_bk7258_spiops;
454	  nxmutex_init(&priv->lock);
455	
456	  return &priv->dev;
457	}
