234	static int alsa_read_frames(audio_capture_t* cap, void* buf,
235	    snd_pcm_uframes_t frames)
236	{
237	    snd_pcm_uframes_t done = 0;
238	    unsigned char* dst = buf;
239	
240	    while (done < frames) {
241	        snd_pcm_sframes_t ret = snd_vela_pcm_readi(cap->handle.pcm,
242	            dst + done * cap->hw_frame_bytes, frames - done);
243	
244	        if (ret == -EAGAIN) {
245	            usleep(10 * 1000);
246	            continue;
247	        }
248	
249	        if (ret == -EPIPE) {
250	            syslog(LOG_WARNING, "[%s] ALSA overrun, preparing capture\n",
251	                TAG);
252	            snd_vela_pcm_prepare(cap->handle.pcm);
253	            continue;
254	        }
255	
256	        if (ret == -ESTRPIPE) {
257	            continue;
258	        }
259	
260	        if (ret < 0) {
261	            return done > 0 ? (int)done : (int)ret;
262	        }
263	
264	        done += (snd_pcm_uframes_t)ret;
265	    }
266	
267	    return (int)done;
268	}
