270	static void downmix_interleaved_s16_to_mono(audio_capture_t* cap,
271	    void* out_buf, const void* in_buf, size_t frames)
272	{
273	    int16_t* out = out_buf;
274	    const int16_t* in = in_buf;
275	
276	    for (size_t i = 0; i < frames; i++) {
277	        int32_t mixed = 0;
278	
279	        for (unsigned int ch = 0; ch < cap->hw_channels; ch++) {
280	            mixed += in[i * cap->hw_channels + ch];
281	        }
282	
283	        out[i] = (int16_t)(mixed / (int32_t)cap->hw_channels);
284	    }
285	}
