287	static int open_alsa_capture(audio_capture_t* cap, const char* dev_path,
288	    unsigned int sample_rate, unsigned int channels,
289	    unsigned int bits_per_sample)
290	{
291	    const char* alsa_name = resolve_alsa_name(dev_path);
292	    snd_pcm_format_t format = capture_format_from_bits(bits_per_sample);
293	    unsigned int attempts[2];
294	    int attempt_count = 0;
295	    int last_ret = -ENODEV;
296	
297	    if ((int)format < 0) {
298	        return -ENOTSUP;
299	    }
300	
301	    attempts[attempt_count++] = channels;
302	    if (channels == 1) {
303	        attempts[attempt_count++] = 3;
304	    }
305	
306	    for (int i = 0; i < attempt_count; i++) {
307	        snd_pcm_t* pcm = NULL;
308	        unsigned int hw_channels = attempts[i];
309	        int ret = snd_vela_pcm_open(&pcm, alsa_name,
310	            SND_VELA_PCM_STREAM_CAPTURE, 0);
311	
312	        if (ret < 0) {
313	            last_ret = ret;
314	            continue;
315	        }
316	
317	        ret = configure_alsa_capture(pcm, format, sample_rate, hw_channels);
318	        if (ret < 0) {
319	            snd_vela_pcm_close(pcm);
320	            last_ret = ret;
321	            continue;
322	        }
323	
324	        cap->backend = AUDIO_CAPTURE_BACKEND_ALSA;
325	        cap->handle.pcm = pcm;
326	        cap->bits_per_sample = bits_per_sample;
327	        cap->requested_channels = channels;
328	        cap->hw_channels = hw_channels;
329	        cap->out_frame_bytes = (bits_per_sample / 8) * channels;
330	        cap->hw_frame_bytes = snd_vela_pcm_frames_to_bytes(pcm, 1);
331	
332	        syslog(LOG_INFO,
333	            "[%s] opened direct ALSA capture (%s, %uHz, req=%uch, hw=%uch, %ubit)\n",
334	            TAG, alsa_name, sample_rate, channels, hw_channels,
335	            bits_per_sample);
336	        return 0;
337	    }
338	
339	    return last_ret;
340	}
