444	audio_capture_t* audio_capture_open(const char* dev_path,
445	    unsigned int sample_rate, unsigned int channels,
446	    unsigned int bits_per_sample)
447	{
448	    if (s_active_capture) {
449	        syslog(LOG_WARNING, "[%s] force closing stale capture\n", TAG);
450	        audio_capture_close(s_active_capture);
451	        usleep(100000);
452	    }
453	
454	    audio_capture_t* cap = calloc(1, sizeof(*cap));
455	    if (!cap) {
456	        return NULL;
457	    }
458	
459	    int ret = -ENOTSUP;
460	
461	    /* Try the portable media_recorder backend FIRST.  On openvela targets
462	     * with a media server (e.g. the goldfish emulator) the media framework
463	     * correctly drives the virtio-snd capture device through the full
464	     * NuttX audio buffer dance.  On devices without a media server (e.g.
465	     * BK7258) media_recorder_open() resolves to a weak stub returning NULL
466	     * immediately, so we fall through to the direct backends below. */
467	    ret = open_media_recorder_capture(cap, sample_rate, channels,
468	        bits_per_sample);
469	    if (ret < 0) {
470	        syslog(LOG_WARNING,
471	            "[%s] media recorder unavailable (%d), trying next backend\n",
472	            TAG, ret);
473	    }
474	
475	#ifdef CONFIG_AI_AGENT_AUDIO_NUTTX_DIRECT
476	    if (ret < 0) {
477	        ret = open_nuttx_capture(cap, dev_path, sample_rate, channels,
478	            bits_per_sample);
479	        if (ret < 0) {
480	            syslog(LOG_WARNING,
481	                "[%s] NuttX audio capture unavailable (%d), trying next backend\n",
482	                TAG, ret);
483	        }
484	    }
485	#else
486	    (void)dev_path;
487	#endif
488	
489	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
490	    if (ret < 0) {
491	        ret = open_alsa_capture(cap, dev_path, sample_rate, channels,
492	            bits_per_sample);
493	        if (ret < 0) {
494	            syslog(LOG_WARNING,
495	                "[%s] direct ALSA capture unavailable (%d)\n", TAG, ret);
496	        }
497	    }
498	#endif
499	
500	    if (ret < 0) {
501	        free(cap);
502	        return NULL;
503	    }
504	
505	    s_active_capture = cap;
506	    return cap;
507	}
