583	int audio_capture_read(audio_capture_t* cap, void* buf, size_t len)
584	{
585	    if (!cap || !buf || len == 0) {
586	        return -EINVAL;
587	    }
588	
589	    switch (cap->backend) {
590	    case AUDIO_CAPTURE_BACKEND_NUTTX: {
591	#ifdef CONFIG_AI_AGENT_AUDIO_NUTTX_DIRECT
592	        ssize_t n;
593	
594	        if (cap->handle.fd < 0) {
595	            return -EINVAL;
596	        }
597	
598	        n = read(cap->handle.fd, buf, len);
599	        if (n < 0) {
600	            return -errno;
601	        }
602	
603	        if (n > 0 && cap->bits_per_sample == 16) {
604	            apply_capture_gain(buf, (size_t)n);
605	        }
606	
607	        return (int)n;
608	#else
609	        return -ENOTSUP;
610	#endif
611	    }
612	
613	    case AUDIO_CAPTURE_BACKEND_ALSA: {
614	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
615	        snd_pcm_uframes_t frames;
616	        int nframes;
617	        size_t out_len;
618	
619	        if (!cap->handle.pcm || cap->out_frame_bytes == 0) {
620	            return -EINVAL;
621	        }
622	
623	        frames = len / cap->out_frame_bytes;
624	        if (frames == 0) {
625	            return -EINVAL;
626	        }
627	
628	        if (cap->hw_channels == cap->requested_channels) {
629	            nframes = alsa_read_frames(cap, buf, frames);
630	            if (nframes <= 0) {
631	                return nframes;
632	            }
633	
634	            out_len = (size_t)nframes * cap->out_frame_bytes;
635	            if (cap->bits_per_sample == 16) {
636	                apply_capture_gain(buf, out_len);
637	            }
638	            return (int)out_len;
639	        }
640	
641	        if (cap->bits_per_sample != 16 || cap->requested_channels != 1) {
642	            return -ENOTSUP;
643	        }
644	
645	        if (ensure_scratch_capacity(cap, frames * cap->hw_frame_bytes) < 0) {
646	            return -ENOMEM;
647	        }
648	
649	        nframes = alsa_read_frames(cap, cap->scratch, frames);
650	        if (nframes <= 0) {
651	            return nframes;
652	        }
653	
654	        downmix_interleaved_s16_to_mono(cap, buf, cap->scratch,
655	            (size_t)nframes);
656	        out_len = (size_t)nframes * cap->out_frame_bytes;
657	        apply_capture_gain(buf, out_len);
658	        return (int)out_len;
659	#else
660	        return -ENOTSUP;
661	#endif
662	    }
663	
664	    case AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER: {
665	        ssize_t n;
666	
667	        if (!cap->handle.recorder) {
668	            return -EINVAL;
669	        }
670	
671	        n = media_recorder_read_data(cap->handle.recorder, buf, len);
672	        if (n > 0 && cap->bits_per_sample == 16) {
673	            apply_capture_gain(buf, (size_t)n);
674	        }
675	
676	        return (int)n;
677	    }
678	
679	    default:
680	        return -EINVAL;
681	    }
682	}
