731	void audio_capture_close(audio_capture_t* cap)
732	{
733	    if (!cap) {
734	        return;
735	    }
736	
737	    switch (cap->backend) {
738	    case AUDIO_CAPTURE_BACKEND_NUTTX:
739	#ifdef CONFIG_AI_AGENT_AUDIO_NUTTX_DIRECT
740	        if (cap->handle.fd >= 0) {
741	            if (cap->started) {
742	                ioctl(cap->handle.fd, AUDIOIOC_STOP, 0);
743	                cap->started = 0;
744	            }
745	            close(cap->handle.fd);
746	            cap->handle.fd = -1;
747	        }
748	#endif
749	        break;
750	
751	    case AUDIO_CAPTURE_BACKEND_ALSA:
752	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
753	        if (cap->handle.pcm) {
754	            if (cap->started) {
755	                snd_vela_pcm_drop(cap->handle.pcm);
756	            }
757	            snd_vela_pcm_close(cap->handle.pcm);
758	            cap->handle.pcm = NULL;
759	        }
760	        free(cap->scratch);
761	        cap->scratch = NULL;
762	        cap->scratch_size = 0;
763	#endif
764	        break;
765	
766	    case AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER:
767	        if (cap->handle.recorder) {
768	            media_recorder_stop(cap->handle.recorder);
769	            usleep(50 * 1000);
770	            media_recorder_close(cap->handle.recorder);
771	            cap->handle.recorder = NULL;
772	        }
773	        break;
774	
775	    default:
776	        break;
777	    }
778	
779	    if (s_active_capture == cap) {
780	        s_active_capture = NULL;
781	    }
782	
783	    free(cap);
784	    syslog(LOG_INFO, "[%s] closed\n", TAG);
785	}
